def group_states(grid, start, goal):
    visited = set()
    groups = []

    def dfs(i, j):
        if (i, j) == (start//3, start%3):
            return [start]

        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            x, y = i + dx, j + dy
            if 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] != "X" and (x, y) not in visited:
                visited.add((x, y))
                path = dfs(x, y)
                if path:
                    return [start] + path

        return []

    visited.add((start//3, start%3))
    path = dfs(start//3, start%3)
    if path:
        groups.append(path)

grid = [["X", 0, 6], [1, 2, 4], ["X", 3, 5]]
start = 0
groups = group_states(grid, start, grid[0][0])

